// The Error Trigger hands over the whole failed execution. Pull out the
// few fields a human needs at 2am and add the judgement the raw payload
// cannot make: is re-running this safe?
const e = $input.first().json;

const workflowName = e.workflow?.name ?? 'unknown workflow';
const workflowId   = e.workflow?.id ?? 'unknown';
const failedNode   = e.execution?.lastNodeExecuted ?? 'unknown node';
const message      = e.execution?.error?.message ?? 'no error message';
const executionUrl = e.execution?.url ?? null;
const mode         = e.execution?.mode ?? 'unknown';

// Re-running is safe only when every write the workflow performs is
// idempotent. That is a property of the workflow, not of the error, so it
// is declared here per workflow rather than guessed from the message.
const REPLAY_SAFE_WORKFLOWS = ['Sync orders to 3PL', 'Refresh CRM enrichment'];
const replaySafe = REPLAY_SAFE_WORKFLOWS.includes(workflowName);

// A timeout or a 5xx may well have completed on the server side. Saying
// "just re-run it" without knowing that is how one outage becomes two.
const ambiguous = /timeout|ETIMEDOUT|ECONNRESET|socket hang up|502|503|504/i.test(message);

let verdict;
if (replaySafe) {
  verdict = 'Safe to re-run: every write in this workflow is idempotent.';
} else if (ambiguous) {
  verdict = 'DO NOT blind re-run: the request may have succeeded server-side. Check the downstream system first.';
} else {
  verdict = 'Re-run only after confirming no partial write occurred.';
}

const text = [
  `:rotating_light: *${workflowName}* failed`,
  `*Node:* ${failedNode}`,
  `*Error:* ${message}`,
  `*Mode:* ${mode}`,
  executionUrl ? `*Execution:* ${executionUrl}` : `*Workflow ID:* ${workflowId}`,
  `*Re-run:* ${verdict}`
].join('\n');

return [{ json: { text, workflowName, failedNode, message, executionUrl, replaySafe, ambiguous } }];
